parameters.functionCode:
const aiResponse = $node['Generate MVP with AI'].json.choices[0].message.content;
const ideaData = $node['New Idea Submission'].json;

// Extract code blocks from AI response
const codeBlocks = [];
const htmlMatch = aiResponse.match(/```html([\s\S]*?)```/i);
const cssMatch = aiResponse.match(/```css([\s\S]*?)```/i);
const jsMatch = aiResponse.match(/```javascript([\s\S]*?)```/i);

if (htmlMatch) {
  codeBlocks.push({
    filename: 'index.html',
    content: htmlMatch[1].trim(),
    type: 'html'
  });
}

if (cssMatch) {
  codeBlocks.push({
    filename: 'style.css',
    content: cssMatch[1].trim(),
    type: 'css'
  });
}

if (jsMatch) {
  codeBlocks.push({
    filename: 'script.js',
    content: jsMatch[1].trim(),
    type: 'javascript'
  });
}

// Generate a project ID
const projectId = `vibe_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

return {
  project_id: projectId,
  idea_title: ideaData.idea_title,
  idea_description: ideaData.idea_description,
  code_files: codeBlocks,
  ai_response: aiResponse,
  created_at: new Date().toISOString(),
  user_email: ideaData.user_email
};

const feedbackAnalysis = JSON.parse($node['Analyze Feedback Sentiment'].json.choices[0].message.content);
const projectId = $node['User Feedback Received'].json.project_id;

// Determine if auto-iteration should be triggered
const shouldIterate = (
  feedbackAnalysis.urgency_score >= 7 || 
  feedbackAnalysis.sentiment === 'negative' ||
  feedbackAnalysis.suggested_improvements.length >= 3
);

return {
  should_iterate: shouldIterate,
  project_id: projectId,
  feedback_analysis: feedbackAnalysis,
  iteration_reason: shouldIterate ? 'High urgency feedback received' : 'Low priority feedback'
};

